//! Git credential proxy (in-memory credential relay for ephemeral VMs).
//!
//! Design: `docs/01-architecture-and-sync.md` §6.4.
//!
//! Ephemeral VMs and sandbox nodes never store a personal SSH private key or a
//! long-lived GitHub PAT on the VM disk. When `git clone` / `git fetch` / `git push`
//! runs inside the VM, Git invokes the `GIT_ASKPASS` helper
//! (`~/.flexagent/git-askpass.sh`, generated by [`crate::daemon`]), and the helper
//! queries the daemon over local IPC (`fxg git-askpass`). The daemon uses the
//! [`CredentialBroker`] to send a `GitCredentialRequest` over the existing
//! Node <-> Server connection (WS / stdio pipe) and returns the token received in
//! the `GitCredentialResponse` to the helper **in memory only**.

use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex, RwLock};
use std::time::Duration;

use fxg_protocol::config::DEFAULT_GIT_USERNAME;
use fxg_protocol::node_server::NodeToServerMsg;
use fxg_protocol::util::uuid_v7;
use tokio::sync::{mpsc, oneshot};

use crate::error::NodeError;

/// Timeout for waiting on a `GitCredentialRequest` response.
pub const CREDENTIAL_TIMEOUT: Duration = Duration::from_secs(30);

/// Git credentials returned by the central server (in memory only).
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct CredentialResponse {
    /// Basic auth username
    pub username: String,
    /// Token (`None` when resolution failed)
    pub token: Option<String>,
    /// Error message on failure
    pub error: Option<String>,
}

/// Error returned when the Git credential proxy is unavailable (passed through to the CLI).
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CredentialError {
    /// Not connected to the central server
    NotConnected,
    /// Response timed out
    Timeout,
    /// The server failed to resolve the credential
    Server(String),
}

impl std::fmt::Display for CredentialError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::NotConnected => f.write_str(
                "git credential proxy is unavailable (not connected to a central server)",
            ),
            Self::Timeout => f.write_str("git credential request timed out"),
            Self::Server(message) => write!(f, "git credential request failed: {message}"),
        }
    }
}

struct BrokerInner {
    /// Send queue of the Node <-> Server connection (`None` when disconnected).
    outbound: RwLock<Option<mpsc::Sender<NodeToServerMsg>>>,
    /// Requests awaiting a response (`request_id` -> oneshot)
    pending: Mutex<HashMap<String, oneshot::Sender<CredentialResponse>>>,
}

/// Broker relaying Git credentials (one per daemon).
#[derive(Clone)]
pub struct CredentialBroker {
    inner: Arc<BrokerInner>,
}

impl std::fmt::Debug for CredentialBroker {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("CredentialBroker").finish_non_exhaustive()
    }
}

impl Default for CredentialBroker {
    fn default() -> Self {
        Self::new()
    }
}

impl CredentialBroker {
    /// Creates an empty broker.
    pub fn new() -> Self {
        Self {
            inner: Arc::new(BrokerInner {
                outbound: RwLock::new(None),
                pending: Mutex::new(HashMap::new()),
            }),
        }
    }

    /// Registers the send queue when connecting to the central server (sync worker /
    /// stdio transport only).
    pub fn attach(&self, outbound: mpsc::Sender<NodeToServerMsg>) {
        *self.inner.outbound.write().expect("outbound lock poisoned") = Some(outbound);
    }

    /// Clears the send queue on disconnect (pending requests fail with a timeout).
    pub fn detach(&self) {
        *self.inner.outbound.write().expect("outbound lock poisoned") = None;
    }

    /// Delivers a `GitCredentialResponse` to the pending request.
    pub fn complete(&self, request_id: &str, response: CredentialResponse) {
        if let Some(tx) = self
            .inner
            .pending
            .lock()
            .expect("pending lock poisoned")
            .remove(request_id)
        {
            fxg_protocol::discard_with!(
                tx.send(response),
                "send a message to a channel that may be closed"
            );
        }
    }

    /// Resolves credentials from a Git askpass prompt.
    ///
    /// Extracts the host from the URL in the prompt, sends a `GitCredentialRequest`
    /// to the central server, and waits for the response.
    pub async fn resolve(&self, prompt: &str) -> Result<CredentialResponse, CredentialError> {
        let host = parse_host(prompt).unwrap_or_default();
        let repo_url = parse_url(prompt).unwrap_or(host);
        let outbound = self
            .inner
            .outbound
            .read()
            .expect("outbound lock poisoned")
            .clone()
            .ok_or(CredentialError::NotConnected)?;

        let request_id = uuid_v7();
        let (tx, rx) = oneshot::channel();
        self.inner
            .pending
            .lock()
            .expect("pending lock poisoned")
            .insert(request_id.clone(), tx);

        let message = NodeToServerMsg::GitCredentialRequest {
            request_id: request_id.clone(),
            repo_url,
            // GIT_ASKPASS cannot distinguish clone / fetch / push, so send the
            // generic value `fetch` (the server resolves it the same way)
            operation: "fetch".to_owned(),
        };
        if outbound.send(message).await.is_err() {
            self.inner
                .pending
                .lock()
                .expect("pending lock poisoned")
                .remove(&request_id);
            return Err(CredentialError::NotConnected);
        }

        match tokio::time::timeout(CREDENTIAL_TIMEOUT, rx).await {
            Ok(Ok(response)) => Ok(response),
            Ok(Err(_)) => Err(CredentialError::NotConnected),
            Err(_) => {
                self.inner
                    .pending
                    .lock()
                    .expect("pending lock poisoned")
                    .remove(&request_id);
                Err(CredentialError::Timeout)
            }
        }
    }
}

/// Extracts the URL from a Git askpass prompt.
///
/// Example: `Password for 'https://user@github.com':` -> `https://user@github.com`.
pub fn parse_url(prompt: &str) -> Option<String> {
    let start = prompt.find("'")?;
    let rest = &prompt[start + 1..];
    let end = rest.find("'")?;
    let url = &rest[..end];
    if url.contains("://") {
        Some(url.to_owned())
    } else {
        None
    }
}

/// Extracts only the hostname from a Git askpass prompt.
pub fn parse_host(prompt: &str) -> Option<String> {
    let url = parse_url(prompt)?;
    let rest = url.split("://").nth(1)?;
    let authority = rest.split('/').next()?;
    let host = authority
        .rsplit_once('@')
        .map(|(_, host)| host)
        .unwrap_or(authority);
    let host = host.split(':').next()?;
    if host.is_empty() {
        None
    } else {
        Some(host.to_owned())
    }
}

/// Whether the prompt asks for a username (as opposed to a password).
pub fn prompt_wants_username(prompt: &str) -> bool {
    prompt.to_ascii_lowercase().contains("username")
}

/// Path of the `GIT_ASKPASS` helper script (`~/.flexagent/git-askpass.sh` / `.cmd`).
pub fn askpass_script_path(fxg_home: &Path) -> PathBuf {
    if cfg!(windows) {
        fxg_home.join("git-askpass.cmd")
    } else {
        fxg_home.join("git-askpass.sh")
    }
}

/// Generates the `GIT_ASKPASS` helper script (overwritten every time).
///
/// The script is a thin wrapper that only calls `fxg internal git-askpass <prompt>`; the
/// actual work (relaying a `GitCredentialRequest` to the central server) is done by
/// the daemon. If the daemon is not running, the script exits non-zero and Git
/// stops as an authentication failure (design that never writes tokens to disk:
/// docs/01 §6.4).
pub fn write_askpass_script(fxg_home: &Path) -> Result<PathBuf, NodeError> {
    let binary = std::env::current_exe().map_err(NodeError::Plain)?;
    let path = askpass_script_path(fxg_home);
    let content = if cfg!(windows) {
        format!(
            "@echo off\r\n\"{}\" internal git-askpass %*\r\n",
            binary.display()
        )
    } else {
        format!(
            "#!/bin/sh\n# fxg GIT_ASKPASS proxy (auto-generated). Do not edit.\nexec \"{}\" internal git-askpass \"$1\"\n",
            binary.display()
        )
    };
    std::fs::write(&path, content).map_err(|source| NodeError::Io {
        path: path.clone(),
        source,
    })?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let metadata = std::fs::metadata(&path).map_err(|source| NodeError::Io {
            path: path.clone(),
            source,
        })?;
        let mut permissions = metadata.permissions();
        permissions.set_mode(0o755);
        std::fs::set_permissions(&path, permissions).map_err(|source| NodeError::Io {
            path: path.clone(),
            source,
        })?;
    }
    Ok(path)
}

/// Returns the Git environment variables injected into agent processes
/// (`GIT_ASKPASS` proxy + interactive prompt disabled).
pub fn git_env(fxg_home: &Path) -> Vec<(String, String)> {
    vec![
        (
            "GIT_ASKPASS".to_owned(),
            askpass_script_path(fxg_home).to_string_lossy().into_owned(),
        ),
        // Prevent Git from hanging while waiting for user input in an environment
        // without a terminal
        ("GIT_TERMINAL_PROMPT".to_owned(), "0".to_owned()),
    ]
}

/// Default credential username.
pub fn default_username() -> &'static str {
    DEFAULT_GIT_USERNAME
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parse_host_extracts_github_from_askpass_prompt() {
        let prompt = "Password for 'https://user@github.com': ";
        assert_eq!(parse_host(prompt).as_deref(), Some("github.com"));
        assert_eq!(
            parse_url(prompt).as_deref(),
            Some("https://user@github.com")
        );
        assert_eq!(
            parse_host("Username for 'https://gitlab.example.com:8443/x/y':").as_deref(),
            Some("gitlab.example.com")
        );
        assert_eq!(parse_host("Password:"), None);
        assert!(prompt_wants_username("Username for 'https://github.com':"));
        assert!(!prompt_wants_username(
            "Password for 'https://x@github.com':"
        ));
    }

    #[tokio::test]
    async fn resolve_without_connection_fails() {
        let broker = CredentialBroker::new();
        let err = broker.resolve("Password for 'https://github.com':").await;
        assert_eq!(err, Err(CredentialError::NotConnected));
    }

    #[tokio::test]
    async fn resolve_forwards_request_and_completes() {
        let broker = CredentialBroker::new();
        let (tx, mut rx) = mpsc::channel(4);
        broker.attach(tx);

        let pending = {
            let broker = broker.clone();
            tokio::spawn(async move { broker.resolve("Password for 'https://github.com':").await })
        };
        let message = rx.recv().await.expect("request");
        let NodeToServerMsg::GitCredentialRequest {
            request_id,
            repo_url,
            ..
        } = message
        else {
            panic!("unexpected message: {message:?}");
        };
        assert_eq!(repo_url, "https://github.com");
        broker.complete(
            &request_id,
            CredentialResponse {
                username: "x-access-token".to_owned(),
                token: Some("secret".to_owned()),
                error: None,
            },
        );
        let response = pending.await.expect("join").expect("resolve");
        assert_eq!(response.token.as_deref(), Some("secret"));
    }

    #[test]
    fn askpass_script_is_written() {
        let dir = tempfile::tempdir().expect("tempdir");
        let path = write_askpass_script(dir.path()).expect("write");
        assert!(path.exists());
        let content = std::fs::read_to_string(&path).expect("read");
        assert!(content.contains("internal git-askpass"));
    }
}
